# ── AST node types ─────────────────────────────────────────────────
@dataclass
class NumberLit:
    value: Union[int, float]

@dataclass
class StringLit:
    value: str

@dataclass
class ColumnRef:
    name: str

@dataclass
class BinOp:
    op: str  # '+', '-', '*', '/', '++'
    left: ExprNode
    right: ExprNode

@dataclass
class UnaryMinus:
    operand: ExprNode

@dataclass
class FuncCall:
    name: str
    args: List[ExprNode]

ExprNode = Union[NumberLit, StringLit, ColumnRef, BinOp, UnaryMinus, FuncCall]

# ── Tokenizer ──────────────────────────────────────────────────────
@dataclass
class Token:
    kind: str   # 'NUM', 'STR', 'ID', 'OP', 'LPAREN', 'RPAREN', 'COMMA'
    value: Any
    pos: int

TOKEN_RE = re.compile(
    r"""
        \s+                                          # whitespace (skip)
      | (?P<str>  "(?:[^"\\]|\\.)*")                 # double-quoted string
      | (?P<num>  \d+\.\d+)                         # float literal
      | (?P<numi> \d+)                               # int literal
      | (?P<op>   \/|\*|\+\+|\+|-)                   # operators (longest first)
      | (?P<lpar> \()                                # left paren
      | (?P<rpar> \))                                # right paren
      | (?P<comma>,)                                 # comma
      | (?P<id>   [A-Za-z_][A-Za-z0-9_]*)           # identifier / function name
    """,
    re.VERBOSE,
)

def tokenize(expr: str) -> List[Token]:
    if not expr.strip():
        raise ComputeError("empty expression")
    tokens: List[Token] = []
    for m in TOKEN_RE.finditer(expr):
        # skip whitespace
        if m.group(0).isspace():
            continue
        kind_map = {
            'str': ('STR', _unescape_string(m.group())),
            'num':  ('NUM', float(m.group())),
            'numi': ('NUM', int(m.group())),
            'op':   ('OP', m.group()),
            'lpar': ('LPAREN', '('),
            'rpar': ('RPAREN', ')'),
            'comma':('COMMA', ','),
            'id':   ('ID', m.group()),
        }
        kind, value = kind_map[m.lastgroup]
        tokens.append(Token(kind=kind, value=value, pos=m.start()))
    return tokens

def _unescape_string(s: str) -> str:
    """Remove surrounding quotes and process escape sequences."""
    s = s[1:-1]  # strip outer quotes
    out = []
    i = 0
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s):
            c = s[i + 1]
            escape_map = {'n': '\n', 't': '\t', 'r': '\r', '"': '"', '\\': '\\'}
            out.append(escape_map.get(c, c))
            i += 2
        else:
            out.append(s[i])
            i += 1
    return ''.join(out)

# ── Recursive-descent parser ───────────────────────────────────────
class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Optional[Token]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind: str, value: Any = None) -> Token:
        tok = self.peek()
        if tok is None or tok.kind != kind or (value is not None and tok.value != value):
            expected = f"{kind} {value}" if value else kind
            got = f"{tok.kind} '{tok.value}' at pos {tok.pos}" if tok else "end of input"
            raise ComputeError(f"syntax error: expected {expected}, got {got}")
        return self.advance()

    def parse(self) -> ExprNode:
        node = self.parse_addition()  # +, -, ++ all at same level
        if self.peek() is not None:
            tok = self.peek()
            raise ComputeError(f"unexpected token '{tok.value}' at position {tok.pos}")
        return node

    # Addition → Term (('+' | '-' | '++') Term)*
    def parse_addition(self) -> ExprNode:
        left = self.parse_term()
        while True:
            tok = self.peek()
            if tok and tok.kind == 'OP' and tok.value in ('+', '-', '++'):
                op = self.advance().value
                right = self.parse_term()
                left = BinOp(op=op, left=left, right=right)
            else:
                break
        return left

    # Term → Factor (('*' | '/') Factor)*
    def parse_term(self) -> ExprNode:
        left = self.parse_unary()
        while True:
            tok = self.peek()
            if tok and tok.kind == 'OP' and tok.value in ('*', '/'):
                op = self.advance().value
                right = self.parse_unary()
                left = BinOp(op=op, left=left, right=right)
            else:
                break
        return left

    # Unary → '-' Factor | Primary
    def parse_unary(self) -> ExprNode:
        tok = self.peek()
        if tok and tok.kind == 'OP' and tok.value == '-':
            self.advance()
            operand = self.parse_unary()  # right-associative unary minus
            return UnaryMinus(operand=operand)
        return self.parse_primary()

    # Primary → NumberLit | StringLit | ColumnRef | FuncCall | '(' Expression ')'
    def parse_primary(self) -> ExprNode:
        tok = self.peek()
        if tok is None:
            raise ComputeError("unexpected end of expression")

        if tok.kind == 'NUM':
            self.advance()
            return NumberLit(value=tok.value)

        if tok.kind == 'STR':
            self.advance()
            return StringLit(value=tok.value)

        if tok.kind == 'LPAREN':
            self.advance()  # consume '('
            node = self.parse_addition()
            self.expect('RPAREN', ')')
            return node

        if tok.kind == 'ID':
            name = self.advance().value
            next_tok = self.peek()
            if next_tok and next_tok.kind == 'LPAREN':
                # function call
                self.advance()  # consume '('
                args: List[ExprNode] = []
                if self.peek() and self.peek().kind != 'RPAREN':
                    args.append(self.parse_addition())
                    while True:
                        next_tok2 = self.peek()
                        if next_tok2 and next_tok2.kind == 'COMMA':
                            self.advance()
                            args.append(self.parse_addition())
                        else:
                            break
                self.expect('RPAREN', ')')
                return FuncCall(name=name, args=args)
            else:
                # column reference
                return ColumnRef(name=name)

        raise ComputeError(f"unexpected token '{tok.value}' at position {tok.pos}")

# ── Public API: parse_expr ─────────────────────────────────────────
def parse_expr(expr_str: str) -> ExprNode:
    """Parse an expression string into an AST node."""
    tokens = tokenize(expr_str)
    parser = Parser(tokens)
    return parser.parse()

# ── Helpers ────────────────────────────────────────────────────────
def _is_numeric(val: Any) -> bool:
    """Return True if val is int or float (but not bool)."""
    return isinstance(val, (int, float)) and not isinstance(val, bool)

# ── Evaluator ───────────────────────────────────────────────────────
def eval_row(node: ExprNode, row_dict: dict, schema_cols: List[str]) -> Any:
    """
    Evaluate an AST node against a row dictionary and the current column schema.

    Parameters
    ----------
    node : ExprNode
        The parsed expression tree.
    row_dict : dict
        Mapping of column names to values for the current row.
    schema_cols : list[str]
        List of known column names (used to validate ColumnRef).
    """
    if isinstance(node, NumberLit):
        return node.value

    if isinstance(node, StringLit):
        return node.value

    if isinstance(node, ColumnRef):
        name = node.name
        if name not in schema_cols:
            raise ComputeError(f"unknown column: {name}")
        # If key is missing from row_dict, treat as null (None)
        return row_dict.get(name, None)

    if isinstance(node, UnaryMinus):
        val = eval_row(node.operand, row_dict, schema_cols)
        if val is None:
            raise ComputeError("cannot apply unary - to null")
        if not _is_numeric(val):
            raise ComputeError(f"cannot apply unary - to {type(val).__name__}")
        return -val

    if isinstance(node, BinOp):
        left_val = eval_row(node.left, row_dict, schema_cols)
        right_val = eval_row(node.right, row_dict, schema_cols)

        # String concatenation with ++
        if node.op == '++':
            return str(left_val) + str(right_val)

        # Numeric operators: both operands must be numeric (not string)
        if isinstance(left_val, str):
            raise ComputeError(f"cannot apply {node.op} to strings; use ++ for concat")
        if isinstance(right_val, str):
            raise ComputeError(f"cannot apply {node.op} to strings; use ++ for concat")

        # Handle nulls in numeric ops — propagate null
        if left_val is None or right_val is None:
            return None

        if not _is_numeric(left_val) or not _is_numeric(right_val):
            raise ComputeError(f"cannot apply {node.op} to non-numeric types")

        if node.op == '+':
            return left_val + right_val
        elif node.op == '-':
            return left_val - right_val
        elif node.op == '*':
            return left_val * right_val
        elif node.op == '/':
            if right_val == 0:
                raise ComputeError("division by zero")
            # Return float for division to match Python semantics
            return left_val / right_val
        else:
            raise ComputeError(f"unknown operator: {node.op}")

    if isinstance(node, FuncCall):
        name = node.name.lower()
        args_evaluated = [eval_row(a, row_dict, schema_cols) for a in node.args]

        if name == 'upper':
            if len(args_evaluated) != 1:
                raise ComputeError("upper() takes exactly 1 argument")
            return str(args_evaluated[0]).upper()

        elif name == 'lower':
            if len(args_evaluated) != 1:
                raise ComputeError("lower() takes exactly 1 argument")
            return str(args_evaluated[0]).lower()

        elif name == 'len':
            if len(args_evaluated) != 1:
                raise ComputeError("len() takes exactly 1 argument")
            val = args_evaluated[0]
            if val is None:
                raise ComputeError("cannot apply len to null")
            if isinstance(val, (int, float)) and not isinstance(val, bool):
                raise ComputeError(f"cannot apply len to numeric type {type(val).__name__}")
            try:
                return len(val)
            except TypeError:
                raise ComputeError(f"cannot apply len to {type(val).__name__}")

        elif name == 'round':
            if len(args_evaluated) != 2:
                raise ComputeError("round() takes exactly 2 arguments")
            val = args_evaluated[0]
            n = args_evaluated[1]
            if not _is_numeric(val):
                raise ComputeError(f"cannot apply round to {type(val).__name__}")
            if not isinstance(n, int):
                raise ComputeError("round() second argument must be an integer")
            return round(float(val), n)

        elif name == 'coalesce':
            if len(args_evaluated) != 2:
                raise ComputeError("coalesce() takes exactly 2 arguments")
            for v in args_evaluated:
                if v is not None:
                    return v
            return None

        else:
            raise ComputeError(f"unknown function: {name}")

    raise ComputeError(f"unexpected node type: {type(node).__name__}")
"}
